import hashlib
import json

hash_hex = "a60458d2180258d47d7f7bef5236b33e86711ac926518ca4545ebf24cdc0b76c"

def try_hash(algorithm, word):
    h = hashlib.new(algorithm)
    h.update(word.encode())
    return h.hexdigest().lower() == hash_hex.lower()

algorithms = [
    "md5", "sha1", "sha224", "sha256", "sha384", "sha512",
    "sha3_224", "sha3_256", "sha3_384", "sha3_512",
    "blake2b", "blake2s", "md5-sha1",
    "ripemd128", "ripemd160", "ripemd256", "ripemd320",
    "whirlpool", "tiger", "tiger160", "tiger192",
    "sha512_224", "sha512_256", "sha3_256", "shake_128", "shake_256",
]

found = None
for algo in algorithms:
    try:
        hashlib.new(algo)
    except ValueError:
        continue
    for word in ["example", "password", "test", "flag", "secret", "crack", "hash", "challenge"]:
        if try_hash(algo, word):
            found = (algo, word)
            break
    if found:
        break

if found:
    algo, word = found
    print(f"flag{{{word}}}")
else:
    print("flag{unknown}")
